<script setup lang="ts">
import{computed,reactive,ref}from'vue';import{useRoute}from'vue-router';import{useAuthStore}from'../../stores/auth';import{http}from'../../api/http';import{day}from'../../utils/dates';import RecordPage from '../../components/RecordPage.vue';import type {Definition,Row} from '../../shared/records'
const route=useRoute(),auth=useAuthStore(),date=ref(String(route.query.date??day())),meal=ref('LUNCH'),error=ref(''),message=ref(''),pending=ref(false),record=ref<InstanceType<typeof RecordPage>>(),voucher=ref(''),orderNo=ref(''),elderName=ref(''),verified=ref<Row|null>(null),refund=ref<Row|null>(null),note=ref(''),refundOrder=ref<Row|null>(null)
const mode=computed(()=>route.path.endsWith('/redemptions')?'redemption':route.path.endsWith('/refunds')?'refund':'delivery'),definition=computed<Definition>(()=>mode.value==='refund'?{title:'退单退款审核',endpoint:'/refunds?status='+String(route.query.status??'')+'&siteId='+String(route.query.siteId??''),columns:[['orderNo','订单'],['elderName','老人'],['amount','退款金额'],['reason','原因'],['status','状态']]}:{title:'配送清单',endpoint:`/sites/${auth.currentSiteId??0}/delivery-list?date=${date.value}&mealType=${meal.value}&deliveryStatus=${String(route.query.deliveryStatus??'')}`,columns:[['elderName','老人'],['deliveryAddress','配送地址'],['contactName','联系人'],['contactPhone','联系电话'],['items','餐食'],['dietaryNotes','必要饮食要求'],['deliveryStatus','配送状态']]})
async function redeem(confirm:boolean){if(pending.value)return;pending.value=true;error.value='';try{const body=voucher.value.trim()?{voucher:voucher.value.trim()}:{orderNo:orderNo.value.trim(),elderName:elderName.value.trim()};const order=await http.post<never,Row>(`/redemptions/${confirm?'confirm':'verify'}`,body);if(confirm){message.value=`核销成功：${order.elderName}，${order.orderNo}`;verified.value=null;voucher.value='';orderNo.value='';elderName.value=''}else verified.value=order}catch(e){error.value=(e as Error).message;verified.value=null}finally{pending.value=false}}
async function openRefund(row:Row){note.value='';error.value='';try{refundOrder.value=await http.get(`/orders/${row.orderId}`);refund.value=row}catch(e){error.value=(e as Error).message}}
async function review(action:string){if(pending.value)return;pending.value=true;error.value='';try{await http.post(`/refunds/${refund.value!.id}/${action}`,{note:note.value});refund.value=null;await record.value?.load()}catch(e){error.value=(e as Error).message}finally{pending.value=false}}
function printList(){window.print()}
</script>
<template><section><el-alert v-if="error" :title="error" type="error" :closable="false" role="alert"/><el-alert v-if="message" :title="message" type="success" :closable="false"/><template v-if="mode==='redemption'"><h1>取餐核验与核销</h1><div class="content-card form-stack"><label for="pickup-code">电子取餐凭证</label><el-input id="pickup-code" v-model="voucher" @input="verified=null"/><p>无法出示凭证时，请人工核对订单号及老人姓名。</p><label for="manual-order">订单号</label><el-input id="manual-order" v-model="orderNo" @input="verified=null"/><label for="manual-elder">老人姓名</label><el-input id="manual-elder" v-model="elderName" @input="verified=null"/><el-button type="primary" :loading="pending" @click="redeem(false)">先核验订单</el-button><div v-if="verified"><h2>{{verified.elderName}}</h2><p>{{verified.orderNo}} · {{verified.mealDate}}</p><p v-for="item in verified.items" :key="item.id">{{item.dishNameSnapshot}} × {{item.qty}}</p><el-button type="primary" :loading="pending" @click="redeem(true)">确认已取餐并核销</el-button></div></div></template><template v-else><div v-if="mode==='delivery'" class="toolbar"><el-input v-model="date" type="date" aria-label="配送日期"/><el-select v-model="meal" aria-label="配送餐次"><el-option label="午餐" value="LUNCH"/><el-option label="晚餐" value="DINNER"/></el-select><el-button @click="printList">打印配送单</el-button></div><RecordPage ref="record" :definition="definition"><template #actions="{row,action}"><template v-if="mode==='refund'"><el-button v-if="['PENDING_REVIEW','REFUND_FAILED'].includes(row.status)" link type="primary" @click="openRefund(row)">{{row.status==='REFUND_FAILED'?'重试退款':'审核退款'}}</el-button></template><template v-else><el-button v-if="row.status==='READY'&&row.deliveryStatus==='PENDING'" link @click="action('PATCH',`/orders/${row.id}/delivery-status`,{status:'OUT_FOR_DELIVERY'})">确认出发</el-button><el-button v-if="row.status==='READY'&&row.deliveryStatus==='OUT_FOR_DELIVERY'" link type="primary" @click="action('PATCH',`/orders/${row.id}/delivery-status`,{status:'DELIVERED'})">确认送达</el-button></template></template></RecordPage></template>
<el-dialog :model-value="!!refund" title="退款审核" width="min(600px,94vw)" @close="refund=null"><el-alert v-if="error" :title="error" type="error" :closable="false"/><p>订单 {{refund?.orderNo}}，退款金额 ¥{{refund?.amount}}</p><p v-if="refundOrder">原价 ¥{{refundOrder.originalAmount}} − 补贴 ¥{{refundOrder.subsidyAmount}} = 实付 ¥{{refundOrder.payableAmount}}；退款成功后补贴账本同步冲减一次。</p><label for="refund-note">审核意见</label><el-input id="refund-note" v-model="note" type="textarea"/><div class="toolbar"><el-button type="primary" :loading="pending" @click="review(refund?.status==='REFUND_FAILED'?'retry':'approve')">{{refund?.status==='REFUND_FAILED'?'重试原退款':'批准退款'}}</el-button><el-button v-if="refund?.status==='PENDING_REVIEW'" type="danger" :loading="pending" @click="review('reject')">驳回申请</el-button></div></el-dialog></section></template>
